<template><div class="page"><header><div><h2>Documentos de Caja</h2><p>Emita, descargue y anule documentos con trazabilidad.</p></div><label>Finca<select v-model="fincaId" @change="cargar"><option value="">Seleccione</option><option v-for="f in fincas" :key="f.id" :value="f.id">{{f.code}} - {{f.name}}</option></select></label></header><section class="card"><h3>Nuevo documento</h3><form @submit.prevent="guardar"><label>Tipo<select v-model="form.tipo"><option value="RECIBO_EFECTIVO">Recibo de efectivo</option><option value="VALE_PAGO_MENOR">Vale pago menor</option><option value="ANTICIPO">Anticipo</option><option value="LIQUIDACION_ANTICIPO">Liquidación anticipo</option><option value="REEMBOLSO">Reembolso</option></select></label><label>Fecha<input v-model="form.fecha" type="date" /></label><label>Beneficiario<input v-model.trim="form.beneficiario" required /></label><label>Importe<input v-model.number="form.importe" type="number" min=".01" step=".01" @input="limpiarDenominaciones" /></label><label>Entregado por<input v-model.trim="form.entregadoPor" /></label><label>Recibido por<input v-model.trim="form.recibidoPor" /></label><label>Autorizado por<input v-model.trim="form.autorizadoPor" /></label><label>Referencia<input v-model.trim="form.referencia" /></label><label class="wide">Concepto<input v-model.trim="form.concepto" required /></label><label class="wide">Observaciones<input v-model.trim="form.observaciones" /></label><div class="movimiento wide"><label class="check"><input v-model="form.registrarMovimientoCaja" type="checkbox" /> Registrar movimiento de caja</label><p>Úselo solo para operaciones no liquidadas previamente. Es un movimiento 1:1 y no se activa por defecto.</p><template v-if="form.registrarMovimientoCaja"><label>Sentido<select v-model="form.sentidoCaja"><option value="INGRESO">Ingreso a caja</option><option value="EGRESO">Egreso de caja</option></select></label><strong :class="{error:!cuadra}">Billetes: {{moneda(totalDenominaciones)}} / {{moneda(form.importe)}} {{cuadra?'✓':'Debe cuadrar'}}</strong><div class="denoms"><label v-for="d in denominaciones" :key="d">{{d}} CUP<input v-model.number="conteo[d]" type="number" min="0" step="1" /></label></div></template></div><div><button class="primary" :disabled="!fincaId||!!errorConteo">Emitir</button></div></form></section><section class="card"><h3>Historial</h3><p class="note">Los documentos que afectan caja no se anulan: emita un documento inverso para conservar el control físico.</p><div class="wrap"><table><thead><tr><th>No.</th><th>Tipo</th><th>Fecha</th><th>Beneficiario</th><th>Importe</th><th>Caja</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="d in documentos" :key="d.id"><td>{{d.numero||'—'}}</td><td>{{d.tipo}}</td><td>{{fecha(d.fecha)}}</td><td>{{d.beneficiario}}</td><td class="money">{{moneda(d.importe)}}</td><td>{{d.registrarMovimientoCaja?d.sentidoCaja:'—'}}</td><td>{{d.estado}}</td><td><button class="link" @click="pdf(d)">PDF</button><button v-if="d.estado!=='ANULADO'&&!d.registrarMovimientoCaja" class="link danger" @click="anular(d)">Anular</button><small v-else-if="d.registrarMovimientoCaja">Documento inverso</small></td></tr></tbody></table></div></section></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{notify}from'@/composables/useNotification';import FincaService from'@/services/FincaService';import S,{type DocumentoCaja,type DocumentoCajaRequest}from'@/services/BancoDocumentosCajaService';const denominaciones=[5,10,20,50,100,200,500,1000,2000,5000,10000,20000],fincas=ref<Array<{id:string;code:string;name:string}>>([]),fincaId=ref(''),documentos=ref<DocumentoCaja[]>([]),conteo=reactive<Record<number,number>>(Object.fromEntries(denominaciones.map(d=>[d,0]))),form=reactive({tipo:'RECIBO_EFECTIVO' as DocumentoCajaRequest['tipo'],fecha:new Date().toISOString().slice(0,10),beneficiario:'',importe:0,concepto:'',entregadoPor:'',recibidoPor:'',autorizadoPor:'',referencia:'',observaciones:'',registrarMovimientoCaja:false,sentidoCaja:'INGRESO' as 'INGRESO'|'EGRESO'});const moneda=(x:number)=>`$${(x||0).toLocaleString('es-CU',{minimumFractionDigits:2,maximumFractionDigits:2})}`,fecha=(x?:string)=>x?new Date(x).toLocaleDateString('es-CU'):'—',totalDenominaciones=computed(()=>denominaciones.reduce((s,d)=>s+d*(Number(conteo[d])||0),0)),cuadra=computed(()=>Math.abs(totalDenominaciones.value-form.importe)<.005),errorConteo=computed(()=>form.registrarMovimientoCaja&&(!form.importe||!cuadra.value));function limpiarDenominaciones(){for(const d of denominaciones)conteo[d]=0}async function cargar(){if(!fincaId.value)return;try{documentos.value=(await S.listarDocumentos(fincaId.value)).data||[]}catch(e){console.error(e);notify.error('Error','No se pudieron cargar documentos.')}}async function guardar(){if(!fincaId.value||!form.beneficiario||!form.concepto||form.importe<=0||errorConteo.value)return;try{const r:DocumentoCajaRequest={...form,fincaId:fincaId.value,fecha:`${form.fecha}T00:00:00`,beneficiario:form.beneficiario,entregadoPor:form.entregadoPor||undefined,recibidoPor:form.recibidoPor||undefined,autorizadoPor:form.autorizadoPor||undefined,referencia:form.referencia||undefined,observaciones:form.observaciones||undefined,denominaciones:form.registrarMovimientoCaja?denominaciones.map(denominacion=>({denominacion,cantidad:Math.max(0,Math.trunc(conteo[denominacion]||0))})).filter(x=>x.cantidad>0):undefined};await S.crearDocumento(r);Object.assign(form,{beneficiario:'',importe:0,concepto:'',entregadoPor:'',recibidoPor:'',autorizadoPor:'',referencia:'',observaciones:'',registrarMovimientoCaja:false,sentidoCaja:'INGRESO'});limpiarDenominaciones();await cargar();notify.success('Emitido','Documento registrado.')}catch(e){console.error(e);notify.error('Error','No se pudo emitir.')}}async function anular(d:DocumentoCaja){const o=window.prompt('Observaciones de anulación:');if(!o?.trim())return;try{await S.anularDocumento(d.id,o.trim());await cargar();notify.success('Anulado','Trazabilidad conservada.')}catch(e){console.error(e);notify.error('Error','No se pudo anular.')}}async function pdf(d:DocumentoCaja){try{const r=await S.descargarDocumentoPdf(d.id),u=URL.createObjectURL(new Blob([r.data],{type:'application/pdf'}));window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),60000)}catch(e){console.error(e);notify.error('Error','No se pudo descargar PDF.')}}onMounted(async()=>{try{fincas.value=(await FincaService.buscarFincas({size:999})).data.data||[]}catch(e){console.error(e)}})</script>
<style scoped>.page{max-width:1350px;margin:auto;padding:1.5rem}header{display:flex;justify-content:space-between}.card{border:1px solid #dbe4ea;border-radius:10px;padding:1rem;margin:1rem 0}form{display:grid;grid-template-columns:repeat(4,1fr);gap:.7rem}label{display:grid;gap:.2rem;font-size:.8rem}input,select{padding:.5rem;border:1px solid #cbd5e1;border-radius:5px}.wide{grid-column:span 2}.movimiento{background:#eff6ff;padding:.75rem;border-left:4px solid #2563eb}.check{display:flex;font-weight:700}.movimiento p,.note{color:#64748b;font-size:.82rem}.denoms{display:grid;grid-template-columns:repeat(4,1fr);gap:.4rem}.denoms label{display:flex;align-items:center;gap:.3rem}.denoms input{width:55px}.error{color:#b91c1c}.primary,.link{border:0;border-radius:6px;padding:.6rem;cursor:pointer}.primary{background:#2563eb;color:#fff}.link{background:none;color:#2563eb}.danger{color:#b91c1c}.wrap{overflow:auto}table{width:100%;min-width:750px;border-collapse:collapse}th,td{padding:.55rem;border-bottom:1px solid #e2e8f0;text-align:left}.money{text-align:right}@media(max-width:800px){header{flex-direction:column}form,.denoms{grid-template-columns:1fr}.wide{grid-column:span 1}}</style>
